// ============================================================
// Constants
// ============================================================

// ============================================================
// Type Defaults
// ============================================================
/** * Applies default values to Config fields that are at their zero value. */
export function configDefaults(m: Config): void {
  if (m.httpListen === "") {
    m.httpListen = DEFAULT_HTTP_LISTEN;
  }
  if (m.renewalCheckIntervalSeconds === 0n) {
    m.renewalCheckIntervalSeconds = DEFAULT_RENEWAL_CHECK_INTERVAL_SECONDS;
  }
}
// ============================================================
// Type Undefaults
// ============================================================
/** Resets Config fields that match defaults back to zero for minimal persistence. */
export function configUndefaults(m: Config): void {
  if (m.httpListen === DEFAULT_HTTP_LISTEN) {
    m.httpListen = "";
  }
  if (
    m.renewalCheckIntervalSeconds ===
    BigInt(DEFAULT_RENEWAL_CHECK_INTERVAL_SECONDS)
  ) {
    m.renewalCheckIntervalSeconds = 0n;
  }
}

// ============================================================
// Merge: Config
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeConfig(dst: Config, src: Config): void {
  if (dst.fqdn === "") {
    dst.fqdn = src.fqdn;
  }
  if (dst.letsEncryptEmail === "") {
    dst.letsEncryptEmail = src.letsEncryptEmail;
  }
  if (dst.httpListen === "") {
    dst.httpListen = src.httpListen;
  }
  if (dst.renewalCheckIntervalSeconds === 0n) {
    dst.renewalCheckIntervalSeconds = src.renewalCheckIntervalSeconds;
  }
}
// ============================================================
// Merge: LetsEncryptState
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeLetsEncryptState(
  dst: LetsEncryptState,
  src: LetsEncryptState,
): void {
  if (!dst.certData && src.certData) {
    dst.certData = src.certData;
  } else if (dst.certData && src.certData) {
    mergeLetsEncryptCertData(dst.certData, src.certData);
  }
}
// ============================================================
// Merge: LetsEncryptCertData
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeLetsEncryptCertData(
  dst: LetsEncryptCertData,
  src: LetsEncryptCertData,
): void {
  if (!dst.tlsCert && src.tlsCert) {
    dst.tlsCert = src.tlsCert;
  }
  if (!dst.certmagicState && src.certmagicState) {
    dst.certmagicState = src.certmagicState;
  } else if (dst.certmagicState && src.certmagicState) {
    mergeCertMagicState(dst.certmagicState, src.certmagicState);
  }
  if (dst.lastRenewed === 0n) {
    dst.lastRenewed = src.lastRenewed;
  }
  if (dst.fqdn === "") {
    dst.fqdn = src.fqdn;
  }
  if (!dst.lock && src.lock) {
    dst.lock = src.lock;
  } else if (dst.lock && src.lock) {
    mergeLock(dst.lock, src.lock);
  }
}
// ============================================================
// Merge: CertMagicState
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeCertMagicState(
  dst: CertMagicState,
  src: CertMagicState,
): void {
  if (dst.isDir === false) {
    dst.isDir = src.isDir;
  }
  if (dst.value.length === 0) {
    dst.value = src.value;
  }
  if (dst.modTime === 0n) {
    dst.modTime = src.modTime;
  }
}
// ============================================================
// Merge: Lock
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeLock(dst: Lock, src: Lock): void {
  if (dst.id === "") {
    dst.id = src.id;
  }
  if (dst.counter === 0n) {
    dst.counter = src.counter;
  }
}
